python3 -c "
import numpy as np
lines=open('work/initial.xyz').read().splitlines()
n=int(lines[0])
at=[l.split()[0] for l in lines[2:2+n]]
pos=np.array([[float(x) for x in l.split()[1:4]] for l in lines[2:2+n]])
pairs=[]
for i in range(n):
    for j in range(i+1,n):
        d=np.linalg.norm(pos[i]-pos[j])
        if d<1.0: pairs.append((round(d,3),at[i]+str(i),at[j]+str(j)))
for p in sorted(pairs): print(p)
"
